import { describe, it, expect } from 'vitest';
import {
    encodeBase64, decodeBase64, signSeedKeypair, signDetached, signVerifyDetached,
    boxSeedKeypair, encryptBox, decryptBox, sha512First32, authChallenge,
} from './crypto';
import { format, parse, normalize, isValid } from './backup';
import rawVectors from '../../test/resources/happy-ts-vectors.json';

// The fixture was generated by happy-app's TypeScript; every expected value
// here is a byte-for-byte reference. See TsVectorsTest.kt for the Kotlin side.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const vectors = rawVectors as any;

function hexToBytes(hex: string): Uint8Array {
    const bytes = new Uint8Array(hex.length / 2);
    for (let i = 0; i < bytes.length; i++) bytes[i] = parseInt(hex.substring(i * 2, i * 2 + 2), 16);
    return bytes;
}

function bytesToHex(bytes: Uint8Array): string {
    return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
}

describe('base64', () => {
    it('matches TS vectors', () => {
        for (const v of vectors.base64) {
            const data = hexToBytes(v.dataHex);
            expect(encodeBase64(data, 'base64')).toBe(v.standard);
            expect(encodeBase64(data, 'base64url')).toBe(v.url);
            expect(bytesToHex(decodeBase64(v.standard, 'base64'))).toBe(v.dataHex);
            expect(bytesToHex(decodeBase64(v.url, 'base64url'))).toBe(v.dataHex);
        }
    });
});

describe('Ed25519 sign (libsodium seed)', () => {
    it('matches TS sign vectors', () => {
        for (const v of vectors.sign) {
            const kp = signSeedKeypair(hexToBytes(v.seedHex));
            expect(bytesToHex(kp.publicKey)).toBe(v.publicKeyHex);
            const signature = signDetached(hexToBytes(v.messageHex), kp.secretKey);
            expect(bytesToHex(signature)).toBe(v.signatureHex);
            expect(signVerifyDetached(signature, hexToBytes(v.messageHex), kp.publicKey)).toBe(true);
        }
    });
});

describe('X25519 box (pairing)', () => {
    it('boxSeedKeypair matches TS vectors', async () => {
        for (const v of vectors.boxSeedKeypair) {
            const kp = await boxSeedKeypair(hexToBytes(v.seedHex));
            expect(bytesToHex(kp.publicKey)).toBe(v.publicKeyHex);
            expect(bytesToHex(kp.secretKey)).toBe(v.secretKeyHex);
        }
    });

    it('encryptBox/decryptBox round-trip matches TS bundleHex', () => {
        for (const v of vectors.encryptBox) {
            // Kotlin Bundles.kt consumes random in order: ephemeral secret (32), then nonce (24).
            const randomChunks = [hexToBytes(v.ephemeralSecretKeyHex), hexToBytes(v.nonceHex)];
            let index = 0;
            const scriptedRandom = (size: number): Uint8Array => {
                const chunk = randomChunks[index++];
                if (chunk.length !== size) throw new Error(`scripted random length mismatch: expected ${size}, got ${chunk.length}`);
                return chunk;
            };
            const bundle = encryptBox(hexToBytes(v.dataHex), hexToBytes(v.recipientPublicKeyHex), scriptedRandom);
            expect(index).toBe(2);
            expect(bytesToHex(bundle)).toBe(v.bundleHex);
            const opened = decryptBox(bundle, hexToBytes(v.recipientSecretKeyHex));
            expect(bytesToHex(opened!)).toBe(v.dataHex);
        }
    });
});

describe('authChallenge (POST /v1/auth)', () => {
    it('matches TS authChallenge vectors', () => {
        for (const v of vectors.authChallenge) {
            const challengeBytes = hexToBytes(v.challengeHex);
            const scriptedRandom = (size: number): Uint8Array => {
                if (size !== challengeBytes.length) throw new Error('challenge size mismatch');
                return challengeBytes;
            };
            const result = authChallenge(hexToBytes(v.secretHex), scriptedRandom);
            expect(bytesToHex(result.challenge)).toBe(v.challengeHex);
            expect(bytesToHex(result.signature)).toBe(v.signatureHex);
            expect(bytesToHex(result.publicKey)).toBe(v.publicKeyHex);
            expect(encodeBase64(result.challenge)).toBe(v.requestBody.challenge);
            expect(encodeBase64(result.signature)).toBe(v.requestBody.signature);
            expect(encodeBase64(result.publicKey)).toBe(v.requestBody.publicKey);
        }
    });
});

describe('SecretKeyBackup', () => {
    it('format matches TS vectors', () => {
        for (const v of vectors.secretKeyBackup) {
            expect(format(v.base64url)).toBe(v.formatted);
        }
    });

    it('parse round-trips', () => {
        for (const v of vectors.secretKeyBackup) {
            expect(parse(v.formatted)).toBe(v.base64url);
        }
    });

    it('normalize handles messy input', () => {
        for (const v of vectors.secretKeyBackup) {
            expect(normalize(v.messy)).toBe(v.normalizedMessy);
        }
    });

    it('isValid rejects wrong lengths', () => {
        const valid32 = encodeBase64(new Uint8Array(32).fill(1), 'base64url');
        expect(isValid(valid32)).toBe(true);
        expect(isValid(format(valid32))).toBe(true);
        const invalid31 = encodeBase64(new Uint8Array(31).fill(1), 'base64url');
        expect(isValid(invalid31)).toBe(false);
    });
});

describe('sha512First32 (V2 content key derivation)', () => {
    it('returns 32 bytes', async () => {
        const digest = await sha512First32(new Uint8Array(32).fill(0xab));
        expect(digest.length).toBe(32);
    });
});
